INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3ad1a8b6-a5ea-40e2-a2bc-99caec2d81fc', '21feff02-016d-46e2-bb9d-c27495133b1b', '111. óra: Projektóra', 'Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "46d3f6ba-1ec3-4176-b9b7-847302bf4165", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "867792d3-ce7d-4c2a-92c2-20d6bd960743", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "00871c05-c151-4dd8-9166-30536f473a65", "text": "A tető színét", "isCorrect": false}, {"id": "1f1c7dc8-f3e6-4757-a139-99591182a31d", "text": "Az épület magasságát", "isCorrect": false}, {"id": "e1c06111-2c96-4a7a-89ee-3dc5a1791cdf", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "8b46baa7-5574-44ef-9810-3233bab534c7", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "9ddf7cd1-e7ed-463e-9c92-3c11f639bf30", "text": "Igaz", "isCorrect": true}, {"id": "7501c2b7-bce3-4c61-a1c4-d1a6dfd8f8ce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "63e6cc41-5eb1-4518-8913-a79e83b40b7c", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "08616ca6-c661-4041-a520-63e0fccdcda0", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "0b5daddf-3b4a-4d7e-afc7-d94e477cca7b", "text": "Igaz", "isCorrect": true}, {"id": "fee52d9f-a591-4ef1-b638-71cc2047ae77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "601e3409-7490-49a3-b78e-923c9638051e", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "bf904747-af6c-4859-8210-1ca5a0bda7bc", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "025394cd-0bed-4acf-a32f-449c9936e64f", "text": "Igaz", "isCorrect": true}, {"id": "425c5d64-33f1-4c51-b3ea-19ab65171d78", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "36b8fc5c-8d52-473f-ae45-64465856366d", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('17eb3d70-820e-43ef-b106-978b638f8e10', '21feff02-016d-46e2-bb9d-c27495133b1b', '112. óra: Projektóra II.', 'Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "2fb5ae4f-5cff-4694-afa8-25d33cb2a03e", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "6709fb5c-af51-48b2-b03d-124c22ba43f4", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "1bef5e25-22c4-410f-8e10-b93228721010", "text": "Igaz", "isCorrect": true}, {"id": "e7c09ff9-2e62-4701-b1e6-a7ada0394cd6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "66524ba1-c066-47cd-b683-32b747914496", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "5dfbc38a-8135-4e6c-8726-52a507eed265", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "bb4229ad-e8f7-499a-911b-fe79d214f214", "text": "Gömbökből", "isCorrect": false}, {"id": "fdcb219f-8e5f-46fb-b634-ac2f38f4b15a", "text": "Kúpokból", "isCorrect": false}, {"id": "4e66eef3-e389-447b-9bce-ebcbf1fcfb5a", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "d6355851-f6db-4676-8581-4a08d7124800", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "24ec4894-6b93-4ac4-b139-a2e7b01405af", "text": "Igaz", "isCorrect": true}, {"id": "28b29d2f-3f89-4dc1-9feb-1d526f8be510", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cfe0978a-d6b2-4f26-9b66-c4bdb0eaec62", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "ac954752-857b-4d8b-83ad-384c225d267b", "text": "A projektmunka kreatív megoldásokat ösztönöz.", "type": "true-false", "options": [{"id": "5a6ee11d-8789-4c99-acb3-fe0bb19597b1", "text": "Igaz", "isCorrect": true}, {"id": "2f8b317b-ffbb-43dd-a7a2-7855710c146b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "af45b8de-e360-4faa-a1a0-a47bb675a912", "text": "Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3e2f0c6e-9d7a-4467-886a-6017ab0ede4f', '21feff02-016d-46e2-bb9d-c27495133b1b', '113. óra: Projektóra III.', 'Az elkészített projektek és makettek bemutatása, csoportértékelés.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "17f7949e-5678-4535-bc4f-f82650af2c3a", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "9bc45a7e-096a-4925-ab82-16d1bb707606", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "35f06ca8-69d7-4ee1-a32f-9e41c8685d75", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "f1e13af7-861b-410f-a9cb-98cb0592a81d", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "619a7d32-1f9c-444f-87db-92156b4f86ad", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "ecde650f-e69b-4135-bb55-488da70a16e9", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "9320d302-0a71-4a34-8d8f-d133db315ba7", "text": "Igaz", "isCorrect": true}, {"id": "63b1bb00-b438-4896-bda3-a17f12184f80", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "478cfeef-3807-4d6f-8476-80ac15d07ab3", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "376a50c2-2fb5-4d45-a536-4c6b04acb486", "text": "Igaz", "isCorrect": true}, {"id": "267738f8-e6b6-43cd-ba77-6c53e30d83e1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ad401a4c-f7bb-4f5a-ac64-5b7676c567e5", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "df4e6089-d684-4bc6-a83b-0fed21d9dec8", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "47716498-d4dc-41db-9330-af291c695a84", "text": "Igaz", "isCorrect": true}, {"id": "7b93428b-6336-4176-be01-2a02c6c20e93", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "66b1d88b-c97b-4085-aedb-caa22eb2302a", "text": "A térszemlélet fejlesztése elengedhetetlen a 3D-s tervezéshez.", "type": "true-false", "options": [{"id": "053741c0-40dc-4b3f-a730-368a229bf1ac", "text": "Igaz", "isCorrect": true}, {"id": "aa9065b1-c3c2-4d14-a213-28de4ae9530b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "420a821a-9a64-41c0-973f-dfd524aede68", "text": "Mennyi 1 m³ dm³-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1ab19721-2f7f-4dfc-8f00-97304bf56981', '21feff02-016d-46e2-bb9d-c27495133b1b', '114. óra: Összefoglalás', 'A Kerület, terület, felszín és térfogat fejezet összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "0b88c8b3-3a00-4bfd-996b-6d1f9c403359", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "8b499946-a9d6-48ae-8fa0-a2106161d8ca", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "4eda6868-1c8e-4408-ae9a-3bde70d10bb0", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "0bb61e81-27d1-401f-91f1-f77d8d1d7f11", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "7d0303c6-c3d6-414d-9e84-d4f9941dc720", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "c4102548-5c27-4ba9-9dcc-2787b198d749", "text": "Igaz", "isCorrect": true}, {"id": "cfd5914f-4f9e-48ee-8f46-7f592df4541b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b65c4147-118d-45af-bac9-e1c41d29bb7d", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "c60d0f4a-ab3c-4445-8219-919d96cbda7b", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "77191f1b-be73-4bd2-96fc-f15cc039a602", "text": "Igaz", "isCorrect": true}, {"id": "de8a0eb7-583e-4569-ba99-cc8f06ebb510", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('298265b4-267d-4570-9484-6deab0fe9eb1', '21feff02-016d-46e2-bb9d-c27495133b1b', '115. óra: Gyakorlóóra', 'Gyakorló feladatsor önálló megoldása a mérések témakörben.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "608b651f-4751-4b20-b464-6c15bb4f20d1", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "bb269a71-41b4-4bc7-a4c3-3f403031a484", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "922ec68b-e48b-4838-a85f-5535a799b471", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "df73cb13-7ba6-40ce-8821-115e6d697b06", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "c3683508-d5e4-472d-bb93-1d87ae92efab", "text": "Igaz", "isCorrect": true}, {"id": "0abd52a4-4f41-4abd-be86-d7d3b98b7072", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cbdcf247-337a-4508-96ce-69ab521a736f", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "c3e855f3-895b-4509-9860-a1b8c2d7ed92", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "eaf1c4ba-444d-42b9-8b2a-7666602f16e5", "text": "Igaz", "isCorrect": true}, {"id": "a5f9476b-cdfc-47e1-8566-41e5de24caad", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "92934799-60d9-49fa-be62-cac9c33f7ea1", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0cc1b6c0-1666-4bcd-ae17-797bdfeeaf1b', '21feff02-016d-46e2-bb9d-c27495133b1b', '116. óra: Feladatmegoldás', 'Hétköznapi mérésekkel, kerülettel, területtel és térfogattal kapcsolatos feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "5dff3fed-2418-4b63-9ba1-ec3c6acd6f9f", "text": "Egy 10 m x 8 m-es medence 2 m mély. Hány m³ víz fér a medencébe tele állapotban? (10 * 8 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "93dade16-6429-44e1-921c-2365af668934", "text": "Hány liter víz fér a 160 m³-es medencébe? (160 * 1000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "eeb47727-b4b7-4dd1-aa07-e43f7a55c8ac", "text": "Hány m² csempe kell a medence padlójának leburkolásához? (10 * 8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}, {"id": "8138c31c-ead2-43bd-b0ec-ff3b13304ba1", "text": "A medence térfogata megadja a maximális vízkapacitást.", "type": "true-false", "options": [{"id": "a34ba2e5-7cbc-459e-97da-e15a061d8da5", "text": "Igaz", "isCorrect": true}, {"id": "f4be7044-88b8-4653-a0da-e0ac9af820ce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "41a60309-229b-48ed-b44e-537d95a30afe", "text": "Mennyi a 4 m élű kocka alakú szoba térfogata? (m³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "72c2b5e5-ee94-40dc-b2be-fa84e20f359f", "text": "Mennyi a 4 m élű kocka alakú szoba felszíne? (m²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "e7fc340a-81cf-49c0-98ae-4b427dfcf885", "text": "A gyakorlati feladatok megoldása felkészít a mindennapi életmérésekre.", "type": "true-false", "options": [{"id": "c8f44867-c701-455d-bfb3-dc2559e3abed", "text": "Igaz", "isCorrect": true}, {"id": "a7056