INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('48146d82-14df-4b9f-b12b-a5181423f432', '21feff02-016d-46e2-bb9d-c27495133b1b', '117. óra: Témazáró dolgozat', 'Témazáró számonkérés a Kerület, terület, felszín és térfogat fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "d15946ce-37ea-4f76-b444-53a15292c789", "text": "1. Mennyi a 6 cm és 9 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "294d0126-7a3d-4814-926a-c0914ae2c2a9", "text": "2. Mennyi a 6 cm és 9 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "bca9e04c-e048-42b0-b9cc-5e6dfc3ebec8", "text": "3. Mennyi a 5 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "97e91180-6b8e-4399-b866-8878ff9c0d68", "text": "4. Mennyi a 5 cm élű kocka térfogata? (cm³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "125"}, {"id": "5dffb48b-2ea1-4f8b-95f1-70e3e95c8cee", "text": "5. Mennyi a 3 cm, 4 cm, 6 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}, {"id": "afe1fa01-0419-45af-a051-f2286f79fc9e", "text": "6. Hány cm² 4 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "8fe39d62-b740-470c-a188-d44df0ecd21d", "text": "7. Hány dm³ 3 m³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "0522dd23-4252-44f3-a3af-2e36eee91e1b", "text": "8. Hány liter víz fér el 5 dm³-es edényben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "5ccaca8f-0b02-40fa-b9f0-0ab53551cb23", "text": "9. A derékszögű háromszög területe a befogók szorzatának fele.", "type": "true-false", "options": [{"id": "b280f8f9-17be-4177-9a08-702483f173a9", "text": "Igaz", "isCorrect": true}, {"id": "52ca8aa5-662c-4204-a87d-9f8c3f6c129f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3a5328dc-1704-4c1a-8397-7d2e80afcb20", "text": "10. Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('11ceeaa5-a438-4a7b-8626-df33939c22e9', '21feff02-016d-46e2-bb9d-c27495133b1b', '118. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése és a mérések összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "0b01a718-3468-48dd-af6a-f292b5f6948f", "text": "Mi volt a leggyakoribb hiba a felszín- és térfogatszámítás során?", "type": "multiple-choice", "options": [{"id": "87f527e0-d265-4cd0-a09d-b8e50ae988d3", "text": "A képletek és mértékegységek (cm² vs cm³) összetévesztése", "isCorrect": true}, {"id": "68b923a7-aada-4536-9128-e74c6753bcfe", "text": "A ceruza radírozása", "isCorrect": false}, {"id": "8b9a33a9-847e-40c1-b9e3-8d29c688f6c7", "text": "A számláló írása", "isCorrect": false}, {"id": "c6006698-e815-4ff7-a1b8-f00f0cb83f03", "text": "Az összeadás hiánya", "isCorrect": false}], "timeLimit": 15}, {"id": "8cc7629f-09b9-44ee-a0bb-5fc329de1b29", "text": "A térfogat a test által elfoglalt térrész nagyságát jelenti.", "type": "true-false", "options": [{"id": "3e2736e7-df66-4406-a75b-f02bf4619d21", "text": "Igaz", "isCorrect": true}, {"id": "b3c889b3-681c-45a3-b877-40d7bee7cad8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1b826bfb-6e61-46d1-a134-14a27d29e6d3", "text": "Mennyi a 2 cm élű kocka térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "10541266-947e-4105-bfa8-1ccaae194d08", "text": "Mennyi a 2 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "01780366-a999-44c2-b3fa-d20b76041442", "text": "A mértékegységek helyes megadása a válasz kötelező eleme.", "type": "true-false", "options": [{"id": "de947ca8-0632-480d-bf58-b1e6bf5cdafe", "text": "Igaz", "isCorrect": true}, {"id": "33221e96-3c5e-47cc-b19b-bb30e22d1049", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "50a9422c-d1b8-4811-8caa-222f0e1f3519", "text": "Mennyi a 4 cm és 3 cm befogójú derékszögű háromszög területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "0bd30d34-73f3-43f3-914b-d6620e4339c9", "text": "A hibajavítás segít a pontosabb tudás megszilárdításában.", "type": "true-false", "options": [{"id": "6dbc479d-4216-4266-936d-1f333d55379a", "text": "Igaz", "isCorrect": true}, {"id": "2efc31a6-1b6a-4e8c-9c0b-6beb79d23724", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1b25b5e4-d4d9-48b5-bbdd-f9fbe27da423', '21feff02-016d-46e2-bb9d-c27495133b1b', '119. óra: Játék', 'Adatgyűjtési kifejezések, játékszabályok értelmezése, megfigyelés.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "3cc31b5c-e5f5-4a1c-bfa2-3a21ff7b5fab", "text": "Mi a statisztika fő célja?", "type": "multiple-choice", "options": [{"id": "6f5f9e01-ffe6-4480-8d43-c4eea0834eb9", "text": "Adatok gyűjtése, rendszerezése, ábrázolása és elemzése a döntéshozatalhoz", "isCorrect": true}, {"id": "3e4e27c0-6e91-430f-b83f-dfe97ccd48b4", "text": "Színes rajzok készítése", "isCorrect": false}, {"id": "fe9c9ace-afc5-4df1-8c17-4fb1c4ee6ed1", "text": "Számok törlése", "isCorrect": false}, {"id": "ff26cfb0-9b8a-41fc-85f0-70aab9e0cece", "text": "Csak a legnagyobb szám megtalálása", "isCorrect": false}], "timeLimit": 15}, {"id": "9175f4e1-5c27-4088-a961-0ac19008d4f7", "text": "Az adatok gyűjtése történhet megfigyeléssel, méréssel vagy kérdőívvel.", "type": "true-false", "options": [{"id": "4838cd3f-d5b4-4d3a-8904-1ddf0833380c", "text": "Igaz", "isCorrect": true}, {"id": "34e23ce0-aba8-40fe-aa06-714899b26e8b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eeab8df0-a110-4474-8648-2377964cb486", "text": "Melyik nem statisztikai adatgyűjtési módszer?", "type": "multiple-choice", "options": [{"id": "482c21ce-46e0-493f-a12c-d3c122d74025", "text": "Alvás", "isCorrect": true}, {"id": "3fdd2c39-a81c-4b4d-b968-2dd5db69fda4", "text": "Kérdőíves felmérés", "isCorrect": false}, {"id": "f6cdea08-29f6-4f5f-8769-b5ac62542e05", "text": "Hőmérséklet-mérés", "isCorrect": false}, {"id": "28f627cd-0086-4799-bf6b-f4616aabf52a", "text": "Szavazás", "isCorrect": false}], "timeLimit": 15}, {"id": "a465f081-90ec-4fa9-958b-b2b58576225d", "text": "A gyűjtött adatokat áttekinthető módon táblázatba foglalhatjuk.", "type": "true-false", "options": [{"id": "86031b20-8526-48d7-8bc8-5e2a0cccd095", "text": "Igaz", "isCorrect": true}, {"id": "62e135b0-dafb-4e0b-84b5-139f1b772eb8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b827fa77-ad41-4ee3-ab67-c6ae9a8e7dc0", "text": "Hány válaszlehetőség van egy ''igen/nem'' típusú kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "b52b73c4-c7ce-4a18-8803-85b67bbaab3e", "text": "A statisztikai mintavétel során a cél a pontos és torzításmentes adatszerzés.", "type": "true-false", "options": [{"id": "ec77dd8d-f56a-4543-abd1-e4d353b242f0", "text": "Igaz", "isCorrect": true}, {"id": "60038d9e-2ed7-4f1d-ad24-10b550937fc1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1dc327b5-6163-4bde-a8c4-2205f656ce00", "text": "Az adatok rendszerezése megkönnyíti a döntéshozatalt.", "type": "true-false", "options": [{"id": "ca40cb0a-7744-4caf-acb8-54793ec2b963", "text": "Igaz", "isCorrect": true}, {"id": "5093619c-8d05-445b-b276-1ebc17768e25", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('04b07cdc-9916-4b1f-b026-821da2f9a96d', '21feff02-016d-46e2-bb9d-c27495133b1b', '120. óra: Grafikonok, diagramok, összefüggések', 'Oszlopdiagram, vonaldiagram, pontdiagram és táblázat olvasása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "f6e9bb7a-b25a-49f1-9226-66c289e80dd5", "text": "Mire alkalmas leginkább a vonaldiagram (grafikon)?", "type": "multiple-choice", "options": [{"id": "da85699b-8e1d-4ca6-bbf4-f9ad35dde13d", "text": "Folytonos adatok (pl. hőmérséklet) időbeli változásának szemléltetésére", "isCorrect": true}, {"id": "385595e6-008f-4f87-bd1b-16b33b7441ef", "text": "Egyetlen szám felírására", "isCorrect": false}, {"id": "d21549e0-015f-4827-8031-1c45b0e72e3c", "text": "Betűk csoportosítására", "isCorrect": false}, {"id": "359252c7-97f6-4707-a138-08ee558555b8", "text": "Körök osztására", "isCorrect": false}], "timeLimit": 15}, {"id": "a2bb7b26-6738-4227-930a-e123b2e38af3", "text": "Mire alkalmas az oszlopdiagram?", "type": "multiple-choice", "options": [{"id": "20a65242-c8b3-411c-9309-b8019befecfd", "text": "Különböző kategóriák mennyiségének gyors összehasonlítására oszlopok magasságával", "isCorrect": true}, {"id": "88d06e3e-e1f2-4c65-9385-9998c2f4e7ef", "text": "Számok összeadására", "isCorrect": false}, {"id": "41639556-0d19-41bd-824c-16aebfabec3d", "text": "Csak 2 adat ábrázolására", "isCorrect": false}, {"id": "c1336db2-e4ea-4295-a7d0-fe80a9e39d12", "text": "Videónézésre", "isCorrect": false}], "timeLimit": 15}, {"id": "548bcdb9-c713-4d60-8a88-acd095ed3587", "text": "Ha a diagramon az 1 cm-es oszlop 5 tanulót jelent, hány tanulót jelent a 4 cm-es oszlop?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "2eaf0f73-0c39-49d3-8969-98f05009fa6d", "text": "A diagramok tengelyein jelölni kell a skálát és a mértékegységet.", "type": "true-false", "options": [{"id": "a7eb0eab-e540-4ab1-b812-c7c680e8e823", "text": "Igaz", "isCorrect": true}, {"id": "bdaa0e81-4d07-4b47-8fc9-9caa5413b8fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eae9e984-28f4-4535-be00-ab2a98a635b2", "text": "A táblázat soraiból és oszlopaiból pontos értékek olvashatók le.", "type": "true-false", "options": [{"id": "cc7d88f9-aeb4-4503-b7e5-b6b7c14c7b5a", "text": "Igaz", "isCorrect": true}, {"id": "2095187c-8bf4-4cc2-b82d-7d58f589a298", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5ff3a4e1-03f3-4a6c-a5ef-1fea2e525550", "text": "A hibásan skálázott grafikon félrevezetheti az olvasót.", "type": "true-false", "options": [{"id": "90ab6047-5342-4fe8-9492-5919c5676d1d", "text": "Igaz", "isCorrect": true}, {"id": "76572801-dbfa-454b-87d2-a3e4f4960a04", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "02a95458-7725-49c0-9009-cfe270401853", "text": "Melyik a legmagasabb hőmérséklet, ha a heti mérések: 12°C, 15°C, 18°C, 14°C, 16°C?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;